I maintain an offline reading log. This reducer should return the latest live title for each known book, but it returns the wrong title for this input:

```python
def reduce_events(events, known_books):
    result = {}
    for event in events:
        if event['book_id'] in known_books:
            result[event['book_id']] = event.get('title')
    return result

events = [
    {'event_id': 'e2', 'book_id': 'b1', 'revision': 2, 'action': 'upsert', 'title': 'New'},
    {'event_id': 'e1', 'book_id': 'b1', 'revision': 1, 'action': 'upsert', 'title': 'Old'},
]
```

With `known_books = {'b1'}`, I expect `{'b1': 'New'}`. What is going wrong?

Ignore unknown books before selecting the highest-revision event. Keep delete events in the selection, then omit a book if its winning event is a delete:

```python
if event['book_id'] in known_books:
    previous = latest.get(event['book_id'])
    if previous is None or event['revision'] > previous['revision']:
        latest[event['book_id']] = event

# After the loop:
result = {
    book_id: event.get('title')
    for book_id, event in latest.items()
    if event['action'] != 'delete'
}
```

Initialize `latest = {}` before the loop. Equal revisions still keep the first event encountered; define a tie-breaker if that is not appropriate.

Compare `(revision, event_id)` tuples so the larger event ID breaks revision ties:

```python
if event['book_id'] in known_books:
    previous = latest.get(event['book_id'])
    if previous is None or (event['revision'], event['event_id']) > (
        previous['revision'], previous['event_id']
    ):
        latest[event['book_id']] = event
```

Identical duplicates leave the selection unchanged. Continue omitting a book from the result if its winning event is a delete.

```python
import unittest


def reduce_events(events, known_books):
    latest = {}
    for event in events:
        book_id = event['book_id']
        if book_id not in known_books:
            continue
        previous = latest.get(book_id)
        if previous is None or (event['revision'], event['event_id']) > (
            previous['revision'], previous['event_id']
        ):
            latest[book_id] = event
    return {
        book_id: event.get('title')
        for book_id, event in latest.items()
        if event['action'] != 'delete'
    }


class TestReduceEvents(unittest.TestCase):
    def test_regressions(self):
        def event(event_id, book_id, revision, action, title=None):
            return dict(event_id=event_id, book_id=book_id,
                        revision=revision, action=action, title=title)

        old = event('e1', 'b1', 1, 'upsert', 'Old')
        new = event('e2', 'b1', 2, 'upsert', 'New')
        tie = event('e2', 'b1', 1, 'upsert', 'Winner')
        delete = event('e2', 'b1', 2, 'delete')
        tie_delete = event('e2', 'b1', 1, 'delete')
        early_delete = event('e1', 'b1', 1, 'delete')
        unknown = event('e3', 'b2', 3, 'upsert', 'Unknown')
        cases = [
            ('out of order', [new, old], {'b1': 'New'}),
            ('tie', [tie, old], {'b1': 'Winner'}),
            ('tie reversed', [old, tie], {'b1': 'Winner'}),
            ('duplicate', [old, old.copy()], {'b1': 'Old'}),
            ('winning delete', [old, delete], {}),
            ('losing delete', [early_delete, new], {'b1': 'New'}),
            ('delete wins tie', [old, tie_delete], {}),
            ('unknown book', [unknown], {}),
            ('empty', [], {}),
        ]
        for name, events, expected in cases:
            with self.subTest(name=name):
                self.assertEqual(reduce_events(events, {'b1'}), expected)


if __name__ == '__main__':
    unittest.main()
```

This assumes duplicate IDs have identical payloads and that actions are valid. The tests have not been run here.

